import { readFile, writeFile, mkdir } from 'node:fs/promises';
const names = [
  'react',
  'react-dom',
  '@owlbear-rodeo/sdk',
  'idb',
  'fuse.js',
  'papaparse',
  'lucide-react',
  'uuid',
  'events',
  'js-base64',
  '@fontsource-variable/dm-sans',
  '@fontsource-variable/manrope',
];
let output =
  'Third-party license notices for the Resonance browser distribution.\nDemo WAV files are original synthetic audio generated by scripts/generate-audio.mjs and are dedicated to CC0.\n';
for (const name of names) {
  for (const file of ['LICENSE', 'LICENSE.txt', 'LICENSE.md', 'LICENSE-MIT']) {
    try {
      const license = await readFile(
        new URL(`../node_modules/${name}/${file}`, import.meta.url),
        'utf8',
      );
      output += `\n\n========== ${name} ==========\n\n${license}`;
      break;
    } catch {}
  }
}
await mkdir(new URL('../public/licenses/', import.meta.url), { recursive: true });
await writeFile(new URL('../public/licenses/THIRD-PARTY-NOTICES.txt', import.meta.url), output);
console.log('Collected distribution license notices.');
